using System;using System.Linq;using Musikbox;
class SpeechPhrasesTests {
 static int count;static void Check(bool b,string t){if(!b)throw new Exception(t);count++;Console.WriteLine("OK "+t);}
 static void Main(){var sun=new Song{Artist="Glen Campbell",Title="Sunflower",Album="Country",Source="sun.mp3"};var wilson=new Song{Artist="Lainey Wilson",Title="4x4xU",Album="Whirlwind",Source="wilson.mp3"};var library=new[]{sun,wilson};
  Check(SpeechPhrases.Parse("{\"alternatives\":[{\"text\":\"Sunflower by Glen Campbell\",\"confidence\":0.8},{\"text\":\"\"}],\"text\":\"Sunflower by Glen Campbell\"}").Length==1,"JSON-Alternativen werden ohne Leerwerte und Dubletten gelesen");
  Check(SpeechPhrases.Parse("{\"text\":\"Glen Campbell\"}").Single()=="Glen Campbell","Einzelnes Ergebnis ohne Alternativen bleibt erhalten");Check(SpeechPhrases.Parse("{}").Length==0,"Leeres Ergebnis führt zu keinem Suchtext");Check(SpeechPhrases.Partial("{\"partial\":\"sunflower\"}")=="sunflower","Teilergebnis für sichtbare Rückmeldung gelesen");
  Check(LibrarySearch.VoiceQuery(library,new[]{"Ende A soll auch","Sunflower by Glen Campbell"})=="Sunflower Glen Campbell","Passender englischer Vorschlag gewinnt gegen falsche deutsche Erkennung");Check(LibrarySearch.VoiceQuery(library,new[]{"Suche nach Sunflower von Glen Campbell"})=="Sunflower Glen Campbell","Suchbefehl und von werden vom Bibliothekstext getrennt");Check(LibrarySearch.VoiceQuery(library,new[]{"alle Titel von Glen Campbell"})=="Glen Campbell","Alle Titel eines Interpreten können angefordert werden");Check(LibrarySearch.VoiceQuery(library,new[]{"search for Sunflower by Glen Campbell"})=="Sunflower Glen Campbell","Englische Suchform verarbeitet");
  Check(LibrarySearch.VoiceQuery(library,new[]{"Ende A soll auch"})=="Ende A soll auch","Fehlgehörter Satz wird nicht willkürlich zu Sunflower umgeschrieben");Check(LibrarySearch.VoiceTerm("Lenny Wilson vier mal vier mal you")=="Lainey Wilson 4x4xU","Bisherige Lainey- und 4x4xU-Zuordnung bleibt erhalten");Check(LibrarySearch.VoiceQuery(library,new string[0])=="","Leere Vorschlagsliste sicher verarbeitet");
  bool play;Check(LibrarySearch.PlayTerm("Bitte spiele mir Sunflower",out play)=="Sunflower"&&play,"Wiedergabebefehl bleibt erhalten");Check(LibrarySearch.FindVoice(new[]{sun,sun.Copy()},new[]{"Sunflower Glen Campbell"})==null,"Mehrdeutige Titel werden nicht automatisch abgespielt");Check(SpeechPhrases.Grammar(library,false).Contains("Sunflower von Glen Campbell"),"Windows-Grammatik enthält Titel mit Interpret ohne Spielbefehl");Check(SpeechPhrases.Grammar(library,true).Contains("Sunflower by Glen Campbell"),"Englische Bibliotheksgrammatik vorhanden");
  Check(SpeechPhrases.Peak16(new byte[]{0,0,0,0},4)==0,"Stille hat Pegel null");Check(SpeechPhrases.Peak16(new byte[]{0,128},2)==1,"Negativer PCM-Maximalwert ohne Überlauf verarbeitet");Check(SpeechPhrases.Peak16(new byte[]{0,64,0},3)==.5,"Unvollständiges letztes PCM-Sample wird ignoriert");
  Console.WriteLine("BESTANDEN: "+count+" Sprachparser- und Suchprüfungen; kein Mikrofontest.");
 }
}
